# G0.5-E.2: execute in RStudio with the working directory at the C vMAR root.
# Fixtures MUST be generated by vMAR.Core in R, never by the C implementation.
if (!exists("vmar_neuron_loss_gradient", mode = "function") ||
    !exists("vmar_neuron_field", mode = "function")) {
  library(vMAR.Core)
}

x <- matrix(c(1, 0.5, -0.5, 1.5, 0.7, -1), nrow = 3, byrow = TRUE)
target <- c(0.25, -0.3, 0.7)
theta0 <- c(0.2, -0.4, 0.15)

rows <- list()
for (activation in c("tanh", "sigmoid")) {
  for (method in c("euler", "rk4")) {
    for (dt in c(0.1, 0.025)) {
      for (n_steps in c(1L, 12L)) {
        eta <- 0.3
        initial <- vmar_neuron_loss_gradient(x, target, theta0, activation)
        field <- vmar_neuron_field(x, target, eta, activation)
        advance <- if (method == "euler") vmar_euler_step else vmar_rk4_step
        theta <- theta0
        for (i in seq_len(n_steps))
          theta <- advance(field, (i - 1L) * dt, theta, dt)
        final <- vmar_neuron_loss_gradient(x, target, theta, activation)
        rows[[length(rows) + 1L]] <- data.frame(
          id = paste(activation, method, sprintf("h%.3f", dt),
                     paste0("n", n_steps), sep = "_"),
          activation = activation, integrator = method,
          eta = eta, step = dt, n_steps = n_steps,
          loss_initial = initial$loss,
          grad1 = initial$gradient[1], grad2 = initial$gradient[2],
          grad3 = initial$gradient[3],
          prediction1 = initial$prediction[1],
          prediction2 = initial$prediction[2],
          prediction3 = initial$prediction[3],
          theta1 = theta[1], theta2 = theta[2], theta3 = theta[3],
          loss_final = final$loss)
      }
    }
  }
}

fixtures <- do.call(rbind, rows)
utils::write.csv(fixtures, "reference/vmar_neuron_parity.csv",
                 row.names = FALSE, quote = FALSE)
writeLines(c(paste("R version:", R.version.string),
             paste("vMAR.Core:", as.character(utils::packageVersion("vMAR.Core"))),
             "G0.5-E.2 neuron fixture source: vMAR.Core"),
           "reference/vmar_neuron_parity_metadata.txt")
cat("G0.5-E.2 neuron fixtures generated:", nrow(fixtures), "cases\n")
print(fixtures[, c("id", "loss_initial", "theta1", "theta2", "theta3")],
      row.names = FALSE, digits = 16)
